llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Zalcitabine (ddC) shows 72% absolute oral bioavailability in patients, but it is a stable 2',3'-dideoxycytidine lacking the 5-aza-triazinone ring; the query's 5-aza-2'-deoxycytidine core is acid-labile and a cytidine deaminase substrate, so this high-F evidence does not transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C36"],
      "claim": "Lamivudine has ~95% absolute oral bioavailability, but its oxathiolane cytidine analogue is metabolically stable; the query's 5-aza modification introduces hydrolytic and deaminative liability that dominates oral bioavailability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "Doxifluridine has high oral bioavailability as a fluoropyrimidine nucleoside, but it lacks the 5-aza-triazinone instability of the query, making it an unreliable positive anchor for decitabine.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is decitabine (5-aza-2'-deoxycytidine), whose 5-aza-triazinone base is acid-labile and rapidly deaminated by cytidine deaminase, leading to very low oral bioavailability (<20%). The high-F nucleoside analogues in the evidence lack this modification and are not mechanistically transferable.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for decitabine was provided in the evidence set.",
    "The high-F analogues are structurally similar but lack the 5-aza modification responsible for decitabine's poor oral absorption."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

